import{_ as a,o as r,c as l,a2 as e}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"功能特性","description":"AgoraIn v4 全部功能 —— 课堂日常、考试与阅卷、家校沟通、平台运营","frontmatter":{"title":"功能特性","description":"AgoraIn v4 全部功能 —— 课堂日常、考试与阅卷、家校沟通、平台运营"},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1791175383000}'),o={name:"features.md"};function i(d,t,n,s,h,u){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><p>AgoraIn v4 是<strong>课堂签到与班级教学管理一体机平台</strong>：一套服务端服务多所机构，桌面端断网可用， 识别在本机完成（零 token），数据按机构隔离。</p><p>产品形态：<strong>服务端（Linux）+ 桌面端（Windows）+ Web 管理面板 + 移动端 App + 微信小程序家长端</strong>。</p><h2 id="一、课堂日常" tabindex="-1">一、课堂日常 <a class="header-anchor" href="#一、课堂日常" aria-label="Permalink to &quot;一、课堂日常&quot;">​</a></h2><h3 id="扫码签到" tabindex="-1">扫码签到 <a class="header-anchor" href="#扫码签到" aria-label="Permalink to &quot;扫码签到&quot;">​</a></h3><ul><li>教师生成签到码（教室 / 科目 / 签到密码 / 有效期），学生在 App 扫码或输入短码完成签到</li><li>签到结果经实时通道推送到同班大屏，<strong>前三名金 / 银 / 铜高亮</strong></li><li>打卡数据支持导入导出（CSV），大屏网格行列可配置</li></ul><h3 id="课时管理" tabindex="-1">课时管理 <a class="header-anchor" href="#课时管理" aria-label="Permalink to &quot;课时管理&quot;">​</a></h3><ul><li>课时账户与<strong>划消流水</strong>：划消、赠送、备注，按班按人可查</li><li>与课程表联动：上课下课自动切换场景，课时自动扣减（幂等，不重复扣）</li></ul><h3 id="点名-积分-值日-座位" tabindex="-1">点名 / 积分 / 值日 / 座位 <a class="header-anchor" href="#点名-积分-值日-座位" aria-label="Permalink to &quot;点名 / 积分 / 值日 / 座位&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>点名</td><td>随机加权（近期没点过的优先）/ 顺序 / 指定三种场次；答到 · 缺勤 · 迟到，可联动积分</td></tr><tr><td>积分</td><td>规则（每日上限、适用班级）、流水（手工 / 打卡 / 点名 / 值日 / 答题卡 / 修正）、积分榜；教师修正须填原因并留痕</td></tr><tr><td>值日</td><td>岗位（名称 / 图标 / 人数）、按周或按日轮换生成值日表、完成情况记录</td></tr><tr><td>座位</td><td>布局编辑（行列、讲台方位、禁用空位、分组）、拖拽调座、一键随机换座（自动留存快照）</td></tr></tbody></table><h3 id="课程表" tabindex="-1">课程表 <a class="header-anchor" href="#课程表" aria-label="Permalink to &quot;课程表&quot;">​</a></h3><ul><li>科目 / 作息 / 班级课表维护，支持导入导出 ClassIsland 档案（JSON / YAML）</li><li><strong>一键推送到教室一体机</strong>（ClassIsland 插件同步）</li></ul><h3 id="通知与资源" tabindex="-1">通知与资源 <a class="header-anchor" href="#通知与资源" aria-label="Permalink to &quot;通知与资源&quot;">​</a></h3><ul><li>班级通知支持定时发布，家长端带已读回执统计</li><li>教学资源上传 / 预览 / 下载，并按需下发家长端</li></ul><h3 id="设备集控" tabindex="-1">设备集控 <a class="header-anchor" href="#设备集控" aria-label="Permalink to &quot;设备集控&quot;">​</a></h3><ul><li>打卡设备注册、绑定、心跳与在线状态；控制模式可打开集控 Web 面板</li></ul><h2 id="二、考试与阅卷-完整闭环" tabindex="-1">二、考试与阅卷（完整闭环） <a class="header-anchor" href="#二、考试与阅卷-完整闭环" aria-label="Permalink to &quot;二、考试与阅卷（完整闭环）&quot;">​</a></h2><blockquote><p>出卷 → 生成答题卡 → 打印 → 作答 → 拍照上传 → 识别 → 批改 → 成绩统计</p></blockquote><h3 id="出卷" tabindex="-1">出卷 <a class="header-anchor" href="#出卷" aria-label="Permalink to &quot;出卷&quot;">​</a></h3><ul><li><strong>6 种题型</strong>：单选 / 多选 / 判断 / 填空 / 简答 / 作文；分值、标准答案、评分要点、知识点标签</li><li><strong>文件导题</strong>：上传 docx / pdf / txt 由 AI 自动识题（题目与答案可同一文件，也可分「试卷 + 答案」两个文件）</li><li>缺答案的题可 <strong>AI 生成答案</strong>批量补齐；题库模板可复用</li></ul><h3 id="答题卡" tabindex="-1">答题卡 <a class="header-anchor" href="#答题卡" aria-label="Permalink to &quot;答题卡&quot;">​</a></h3><ul><li>纸型：<strong>A4 / B4 / 8K / 16K / A3</strong> 五种；8K / A3 横向一版两页，一张纸拍一次两页同时识别</li><li><strong>服务端精确分页</strong>：每页独立定位标记 + 页码标定框 + 页脚二维码，多页答卷自动归并且不串页</li><li>考号涂卡或条码；可按班级<strong>批量生成一人一张带条码</strong>的答题卡</li><li><strong>作文纸</strong>：语文格子纸（8mm 格 × 20 列）与英语深色横线纸（行距可调），后台可视化拖拽改版式</li><li>客观题 OMR 采用标准方形框（6 × 4 mm），选项间距 2 mm</li></ul><h3 id="扫卡与识别" tabindex="-1">扫卡与识别 <a class="header-anchor" href="#扫卡与识别" aria-label="Permalink to &quot;扫卡与识别&quot;">​</a></h3><ul><li><strong>扫卡入口</strong>：手机 App 拍照、网页端「动态扫卡」（可接高拍仪）</li><li>扫完即进<strong>后台识别队列</strong>，前台继续扫下一张；扫卡有准入闸门（认不出不落库）</li><li><strong>客观题涂卡识别</strong>：本机完成，<strong>零 token</strong></li><li><strong>填空短答案手写识别</strong>：本地模型，精确匹配才自动给分</li><li><strong>主观题</strong>：多模态模型按评分要点批改；作文按维度点评</li><li>识别成本可控：只有判不准的才交给 AI 或人工</li></ul><h3 id="批改状态机" tabindex="-1">批改状态机 <a class="header-anchor" href="#批改状态机" aria-label="Permalink to &quot;批改状态机&quot;">​</a></h3><p><code>未批 → AI 已批 →（低置信度）待人工 → 已确认</code></p><ul><li>逐题对话框可查看识别内容与 AI 建议分，支持快捷记分键与全屏批改</li><li><strong>只有「已确认」计入成绩</strong>；客观题可设为教师手判</li><li>支持<strong>双判</strong>（两位教师独立评分取平均、超阈值转仲裁）与分题阅卷分配</li></ul><h3 id="成绩统计" tabindex="-1">成绩统计 <a class="header-anchor" href="#成绩统计" aria-label="Permalink to &quot;成绩统计&quot;">​</a></h3><ul><li>按学生总分与按题得分率分析，CSV 导出（Excel 直接打开）</li><li>教师复判与改分全部留痕可追溯</li></ul><h3 id="手写数据自闭环-平台侧能力" tabindex="-1">手写数据自闭环（平台侧能力） <a class="header-anchor" href="#手写数据自闭环-平台侧能力" aria-label="Permalink to &quot;手写数据自闭环（平台侧能力）&quot;">​</a></h3><p>平台可生成<strong>训练卡</strong> → 学生誊抄 → 扫回自动切行 / 切单字 → 本地 OCR 自动判定哪些样本可用 → 抽查纠正 → 导出训练集，用于持续微调自有手写识别模型。数据越攒越准，成本越用越低。</p><h2 id="三、家校沟通" tabindex="-1">三、家校沟通 <a class="header-anchor" href="#三、家校沟通" aria-label="Permalink to &quot;三、家校沟通&quot;">​</a></h2><ul><li><strong>家长端小程序与移动端 App 功能对等</strong>：通知与已读回执、班级资源、考勤 / 积分 / 值日、 成绩概览（受隐私开关控制，<strong>默认关闭</strong>）、与教师留言；支持多孩切换</li><li><strong>绑定方式</strong>：教师端按班级批量生成 <strong>6 位邀请码</strong>（可导出 CSV 打印发放），家长输入即绑定</li><li>留言沟通留痕，不再依赖家长群刷屏</li></ul><h2 id="四、平台运营-多区域-租户" tabindex="-1">四、平台运营（多区域 / 租户） <a class="header-anchor" href="#四、平台运营-多区域-租户" aria-label="Permalink to &quot;四、平台运营（多区域 / 租户）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>机构自助注册</td><td>机构注册后由主区域颁发 <strong>AGRR- 激活码</strong>开通；未激活前成员无法登录，受控功能全部停用</td></tr><tr><td>区域隔离</td><td>班级、学生、打卡、课表、试卷、成绩等全部按区域过滤；登录名格式 <code>用户名@区域</code></td></tr><tr><td>区域功能开关</td><td>按区域开关 7 项能力：AI 功能 / 阅卷与出分 / 答题卡识别与批改 / 设备注册 / 课表管理 / 子用户 / 家长邀请</td></tr><tr><td>AI 额度</td><td>主区域颁发 <strong>AGRT- 额度码</strong>，机构兑换入账；机构也可自配 AI 密钥，不受额度限制</td></tr><tr><td>加密远程存储</td><td>答题卡原图与教学资料以 <strong>AES-256-GCM</strong> 加密后经 WebDAV 上传远程磁盘，按区域分目录；服务器只保留 LRU 缓存</td></tr><tr><td>分级权限</td><td>admin / owner / teacher / student / parent 五级角色 + 24 个权限点矩阵</td></tr><tr><td>离线授权</td><td>RSA 签名激活码，支持设备数量与到期时间</td></tr><tr><td>安装包分发</td><td>官网安装包由平台统一分发（<code>/api/v4/downloads</code>），单连接限速 + 并发保护，附 SHA256 校验</td></tr></tbody></table><h2 id="五、多端形态" tabindex="-1">五、多端形态 <a class="header-anchor" href="#五、多端形态" aria-label="Permalink to &quot;五、多端形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端</th><th>技术栈</th><th>说明</th></tr></thead><tbody><tr><td>服务端</td><td>ASP.NET Core 10 + SQLite</td><td>REST + SignalR + JWT，内置本地识别（OMR / 手写 OCR）</td></tr><tr><td>桌面端</td><td>Avalonia 11</td><td>大屏 / 控制 / 教师三模式，Windows 优先，断网可用</td></tr><tr><td>Web 管理面板</td><td>Vue 3 + Vite</td><td>20 个功能页，服务端托管</td></tr><tr><td>移动端 App</td><td>.NET MAUI</td><td>学生扫码签到、教师拍照扫卡与逐题改分、家长中心</td></tr><tr><td>家长端小程序</td><td>微信小程序</td><td>通知、成绩、值日、留言</td></tr></tbody></table><h2 id="六、差异化亮点" tabindex="-1">六、差异化亮点 <a class="header-anchor" href="#六、差异化亮点" aria-label="Permalink to &quot;六、差异化亮点&quot;">​</a></h2><ol><li><strong>本地优先、离线可用</strong>：桌面端断网照常打卡；客观题涂卡与填空短答案都在本机识别</li><li><strong>识别成本可控</strong>：该校对的本地核对掉，该校准的才调模型</li><li><strong>一张纸管到底</strong>：服务端精确分页 + 页码标定框 + 页脚二维码，多页答卷自动归并且不串页</li><li><strong>一套系统服务多个机构</strong>：多区域隔离、功能开关、激活码与额度码，权限边界在服务端</li><li><strong>隐私与合规先行</strong>：AI 图像外发开关（关闭后不向第三方发送任何作答图像）、境内存储、 远程文件认证加密、未成年人信息保护专章</li></ol><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/guide.html">快速开始</a> · <a href="/deploy.html">部署指南</a> · <a href="/api.html">API 文档</a> · <a href="/faq.html">常见问题</a></li><li>历史版本：<a href="/v3.2/">v3.2 归档</a> · <a href="/v2.8/">v2.8 归档</a> · <a href="/v2.7/">v2.7 归档</a></li></ul>',41)])])}const b=a(o,[["render",i]]);export{c as __pageData,b as default};
